# 1) server_container.mjs — endpoint ekle
src=open(SRC,encoding="utf-8").read()
if MARK in src:
    print("• endpoint zaten uygulanmış (%s) — server_container.mjs'e dokunulmadı."%MARK)
else:
    if ANCHOR not in src:
        print("HATA: anchor bulunamadı: %s — DUR."%ANCHOR); sys.exit(1)
    src=src.replace(ANCHOR, ENDPOINTS.rstrip()+"\n\n"+ANCHOR, 1)
    shutil.copy(SRC, SRC+".bak_retention"); open(SRC,"w",encoding="utf-8").write(src)
    open("/tmp/_ret.mjs","w",encoding="utf-8").write(src)
    r=subprocess.run(["node","--check","/tmp/_ret.mjs"],capture_output=True,text=True)
    if r.returncode!=0:
        shutil.copy(SRC+".bak_retention", SRC); print("HATA node --check:\n"+r.stderr); sys.exit(1)
    print("✓ retention + retention-liste + yazkis endpoint eklendi + node --check geçti.")

# 2) shell yaz (gömülü)
html=base64.b64decode("".join(SHELL_B64.split())).decode("utf-8")
os.makedirs(os.path.dirname(SHELLD),exist_ok=True)
open(SHELLD,"w",encoding="utf-8").write(html)
print("✓ shell yazıldı → %s (%d bayt)"%(SHELLD,len(html)))
print("\nŞimdi: docker build -t krb-assessment:secure . && docker compose up -d --force-recreate krb-assessment")
